fn prime_num(n: u64) -> bool {
    if n < 2 {
        return false; // per problem statement, input is at least 2, but just in case
    }
    // To check primality efficiently, test divisors from 2 up to sqrt(n)
    // If any divides n exactly, n is not prime.
    // Use checked multiplication to prevent overflow (though u64^2 is very large)
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return false;
        }
    }
    true
}